mapper.select:
SELECT id, user_id, sign_date, points, streak_after, ledger_id, created_at
FROM points_sign_in
WHERE user_id = #{userId} AND sign_date = #{signDate}

SELECT sign_date
FROM points_sign_in
WHERE user_id = #{userId}
ORDER BY sign_date DESC
LIMIT #{limitRows}

SELECT id, user_id, task_code, points, ledger_id, created_at
FROM points_task_award
WHERE user_id = #{userId} AND task_code = #{taskCode}

SELECT balance
FROM points_account
WHERE user_id = #{userId}
